// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, AccessorArrayLike } from '@stdlib/types/array';

/**
* Input array.
*/
type InputArray = Collection<number> | AccessorArrayLike<number>;

/**
* Output array.
*/
type OutputArray = Collection<number> | AccessorArrayLike<number>;

/**
* Interface describing `gcross`.
*/
interface Routine {
	/**
	* Computes the cross product of two input strided arrays and assigns the results to an output strided array.
	*
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param z - output array
	* @param strideZ - stride length for `z`
	* @returns output array
	*
	* @example
	* var x = [ 1.0, 2.0, 3.0 ];
	* var y = [ 4.0, 5.0, 6.0 ];
	* var z = [ 0.0, 0.0, 0.0 ];
	*
	* gcross( x, 1, y, 1, z, 1 );
	* // z => [ -3.0, 6.0, -3.0 ]
	*/
	<T extends OutputArray>( x: InputArray, strideX: number, y: InputArray, strideY: number, z: T, strideZ: number ): T;

	/**
	* Computes the cross product of two input strided arrays and assigns the results to an output strided array using alternative indexing semantics.
	*
	* @param x - first input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param y - second input array
	* @param strideY - stride length for `y`
	* @param offsetY - starting index for `y`
	* @param z - output array
	* @param strideZ - stride length for `z`
	* @param offsetZ - starting index for `z`
	* @returns output array
	*
	* @example
	* var x = [ 1.0, 2.0, 3.0 ];
	* var y = [ 4.0, 5.0, 6.0 ];
	* var z = [ 0.0, 0.0, 0.0 ];
	*
	* gcross.ndarray( x, 1, 0, y, 1, 0, z, 1, 0 );
	* // z => [ -3.0, 6.0, -3.0 ]
	*/
	ndarray<T extends OutputArray>( x: InputArray, strideX: number, offsetX: number, y: InputArray, strideY: number, offsetY: number, z: T, strideZ: number, offsetZ: number ): T;
}

/**
* Computes the cross product of two input strided arrays and assigns the results to an output strided array.
*
* @param x - first input array
* @param strideX - stride length for `x`
* @param y - second input array
* @param strideY - stride length for `y`
* @param z - output array
* @param strideZ - stride length for `z`
* @returns output array
*
* @example
* var x = [ 1.0, 2.0, 3.0 ];
* var y = [ 4.0, 5.0, 6.0 ];
* var z = [ 0.0, 0.0, 0.0 ];
*
* gcross( x, 1, y, 1, z, 1 );
* // z => [ -3.0, 6.0, -3.0 ]
*
* @example
* var x = [ 1.0, 2.0, 3.0 ];
* var y = [ 4.0, 5.0, 6.0 ];
* var z = [ 0.0, 0.0, 0.0 ];
*
* gcross.ndarray( x, 1, 0, y, 1, 0, z, 1, 0 );
* // z => [ -3.0, 6.0, -3.0 ]
*/
declare var gcross: Routine;


// EXPORTS //

export = gcross;
